/*!
 * Themeasy — Hotspot Image
 *
 * Behavior layer for the Hotspot Image widget. Opening on mouse hover and on
 * keyboard focus stays pure CSS; this script adds what CSS cannot do:
 *
 * - Click trigger: toggle on click / tap / Enter / Space, one open at a time
 * - Hover trigger on touch: a tap toggles the tooltip (touch screens have no
 *   hover, and iOS Safari never focuses a tapped button)
 * - Placement: a tooltip that would leave the viewport flips to the opposite
 *   side and slides along the edge (the arrow keeps pointing at the pin)
 * - Escape closes click / tap tooltips and dismisses a hovered / focused one
 *   until the pointer and focus leave the point (WCAG 1.4.13)
 * - Outside click / tap closes open tooltips; aria-expanded kept in sync
 * - Idempotent: reset() drops every listener so init() can rebind (Elementor
 *   preview re-renders)
 *
 * Without JS the widget degrades to the CSS hover / focus reveal at the
 * authored position.
 *
 * Single namespace: window.Themeasy.hotspotImage
 * Vanilla JS (no jQuery dependency)
 * Auto-initializes on DOM ready.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  // ------------------------------------------------------------------------
  // Namespace
  // ------------------------------------------------------------------------
  window.Themeasy = window.Themeasy || {}
  window.Themeasy.hotspotImage = window.Themeasy.hotspotImage || {}

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  // ------------------------------------------------------------------------
  // Constants
  // ------------------------------------------------------------------------
  const SELECTOR_WRAPPER    = '.tms-hotspot-image'
  const SELECTOR_POINT      = '.tms-hotspot-image__point'
  const SELECTOR_HOTSPOT    = '.tms-hotspot-image__hotspot'
  const SELECTOR_TOOLTIP    = '.tms-hotspot-image__tooltip'
  const CLASS_TRIGGER_CLICK = 'tms-hotspot-image--trigger-click'
  const CLASS_OPEN_POINT    = 'tms-hotspot-image__point--open'
  const CLASS_OPEN_HOTSPOT  = 'tms-hotspot-image__hotspot--open'
  const CLASS_DISMISSED     = 'tms-hotspot-image__point--dismissed'
  const PROP_SHIFT          = '--tms-hotspot-tooltip-shift'

  // Hover-trigger points the CSS currently shows (pointer on it, or focus in it).
  const SELECTOR_ENGAGED =
    '.tms-hotspot-image--trigger-hover .tms-hotspot-image__point:hover,' +
    '.tms-hotspot-image--trigger-hover .tms-hotspot-image__point:focus-within'

  // Gap kept between a tooltip and the viewport edge.
  const VIEWPORT_GUTTER = 8

  // Distance the arrow keeps from the tooltip's end when the tooltip slides.
  const ARROW_CLEARANCE = 16

  const OPPOSITE = { top: 'bottom', bottom: 'top', left: 'right', right: 'left' }
  const TAP_POINTERS = ['touch', 'pen']

  // Point → AbortController holding every listener bound by bindPoint().
  const bindings = new WeakMap()

  // Hotspot button → pointerType of the press that precedes its click.
  const pressPointers = new WeakMap()

  // Document-level listeners are installed once and handle every widget.
  let documentListenersBound = false

  // ------------------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------------------

  /**
   * Whether the point belongs to a click-triggered widget.
   *
   * @param {HTMLElement} point The point container.
   * @returns {boolean}
   */
  function isClickTrigger(point) {
    const widget = point.closest(SELECTOR_WRAPPER)
    return !!widget && widget.classList.contains(CLASS_TRIGGER_CLICK)
  }

  /**
   * Sync aria-expanded. Only the click trigger renders it (a disclosure); the
   * hover trigger's button is described by its tooltip instead.
   *
   * @param {HTMLElement} button   The hotspot button.
   * @param {boolean}     expanded Open state.
   */
  function setExpanded(button, expanded) {
    if (button.hasAttribute('aria-expanded')) {
      button.setAttribute('aria-expanded', expanded ? 'true' : 'false')
    }
  }

  /**
   * How far a rect spills past one side of the bounds (> 0 = overflow).
   *
   * @param {DOMRect} rect   Tooltip rect.
   * @param {string}  side   top | right | bottom | left.
   * @param {Object}  bounds Visible area.
   * @returns {number}
   */
  function overflowOn(rect, side, bounds) {
    if (side === 'top') return bounds.top - rect.top
    if (side === 'bottom') return rect.bottom - bounds.bottom
    if (side === 'left') return bounds.left - rect.left
    return rect.right - bounds.right
  }

  /**
   * Visible area a tooltip must stay inside: the viewport minus a gutter.
   *
   * @returns {{top: number, right: number, bottom: number, left: number}}
   */
  function getBounds() {
    const root = document.documentElement

    return {
      top: VIEWPORT_GUTTER,
      right: root.clientWidth - VIEWPORT_GUTTER,
      bottom: root.clientHeight - VIEWPORT_GUTTER,
      left: VIEWPORT_GUTTER,
    }
  }

  /**
   * Give a resting tooltip a box to measure. At rest it is display: none
   * (backlog #421), which measures 0 x 0. The returned undo runs before the
   * task ends, so the box is never painted. Transitions stay off around the
   * round trip: a forced style read is where the browser starts them, and the
   * display transition of the resting rule would keep the box in the layout
   * through its fade-out delay.
   *
   * @param {HTMLElement} tooltip The tooltip.
   * @returns {Function} Restores the inline styles.
   */
  function giveLayoutBox(tooltip) {
    // Already displayed (open, or fading out): measure it as it is.
    if (window.getComputedStyle(tooltip).display !== 'none') {
      return function () {}
    }

    const style = tooltip.style
    const display = style.display
    const transition = style.transition

    style.transition = 'none'
    style.display = 'block'

    return function () {
      style.display = display
      // Settle the restored display while transitions are still off.
      tooltip.getBoundingClientRect()
      style.transition = transition
    }
  }

  /**
   * Place a point's tooltip before it shows. Starts from the authored position
   * every time; flips to the opposite side only when that fits better, then
   * slides along the edge (capped so the arrow stays on the tooltip). A
   * resting tooltip gets a box only for the reads (giveLayoutBox).
   *
   * @param {HTMLElement} point The point container.
   */
  function placeTooltip(point) {
    const tooltip = point.querySelector(SELECTOR_TOOLTIP)
    if (!tooltip) return

    if (!tooltip.dataset.preferredPosition) {
      tooltip.dataset.preferredPosition = tooltip.dataset.position || 'top'
    }

    const preferred = tooltip.dataset.preferredPosition
    const bounds = getBounds()

    tooltip.dataset.position = preferred
    tooltip.style.removeProperty(PROP_SHIFT)

    const restoreLayout = giveLayoutBox(tooltip)
    let rect = tooltip.getBoundingClientRect()
    const overflow = overflowOn(rect, preferred, bounds)

    // Main axis: flip.
    if (overflow > 0 && OPPOSITE[preferred]) {
      const opposite = OPPOSITE[preferred]
      tooltip.dataset.position = opposite

      const flipped = tooltip.getBoundingClientRect()

      if (overflowOn(flipped, opposite, bounds) < overflow) {
        rect = flipped
      } else {
        tooltip.dataset.position = preferred
      }
    }

    restoreLayout()

    // Cross axis: slide.
    const position = tooltip.dataset.position
    const horizontal = position === 'top' || position === 'bottom'
    const startOverflow = horizontal ? bounds.left - rect.left : bounds.top - rect.top
    const endOverflow = horizontal ? rect.right - bounds.right : rect.bottom - bounds.bottom
    const maxShift = Math.max(0, (horizontal ? rect.width : rect.height) / 2 - ARROW_CLEARANCE)

    let shift = 0

    if (startOverflow > 0) {
      shift = startOverflow
    } else if (endOverflow > 0) {
      shift = -endOverflow
    }

    shift = Math.round(Math.max(-maxShift, Math.min(maxShift, shift)))

    if (shift !== 0) {
      tooltip.style.setProperty(PROP_SHIFT, shift + 'px')
    }
  }

  /**
   * Close a single hotspot point.
   *
   * @param {HTMLElement} point The point container.
   */
  function closePoint(point) {
    if (!point) return
    if (!point.classList.contains(CLASS_OPEN_POINT)) return

    point.classList.remove(CLASS_OPEN_POINT)

    const button = point.querySelector(SELECTOR_HOTSPOT)
    if (button) {
      button.classList.remove(CLASS_OPEN_HOTSPOT)
      setExpanded(button, false)
    }
  }

  /**
   * Close every open hotspot within the scope (defaults to the whole document).
   *
   * @param {ParentNode} [scope=document] Scope to search.
   * @param {HTMLElement} [skipPoint]    Point that must remain untouched.
   */
  function closeAllOpen(scope, skipPoint) {
    const root = scope || document
    const openPoints = root.querySelectorAll('.' + CLASS_OPEN_POINT)
    openPoints.forEach(function (point) {
      if (skipPoint && point === skipPoint) return
      closePoint(point)
    })
  }

  /**
   * Open a single hotspot point.
   *
   * @param {HTMLElement} point The point container.
   */
  function openPoint(point) {
    if (!point) return

    // Close siblings inside the same widget (one open at a time).
    const widget = point.closest(SELECTOR_WRAPPER)
    if (widget) {
      closeAllOpen(widget, point)
    }

    placeTooltip(point)
    point.classList.remove(CLASS_DISMISSED)
    point.classList.add(CLASS_OPEN_POINT)

    const button = point.querySelector(SELECTOR_HOTSPOT)
    if (button) {
      button.classList.add(CLASS_OPEN_HOTSPOT)
      setExpanded(button, true)
    }
  }

  /**
   * Toggle a single hotspot point.
   *
   * @param {HTMLElement} point The point container.
   */
  function togglePoint(point) {
    if (!point) return
    if (point.classList.contains(CLASS_OPEN_POINT)) {
      closePoint(point)
    } else {
      openPoint(point)
    }
  }

  /**
   * Bind a single point: placement, dismissal bookkeeping and the button.
   *
   * @param {HTMLElement} point The point container.
   */
  function bindPoint(point) {
    if (!point || bindings.has(point)) return

    const controller = new AbortController()
    const options = { signal: controller.signal }
    const clickTrigger = isClickTrigger(point)
    const button = point.querySelector(SELECTOR_HOTSPOT)

    bindings.set(point, controller)

    // Placement runs ahead of the reveal: pointerenter / focusin dispatch before
    // the :hover / :focus-visible style they cause is computed. An already open
    // tooltip keeps its place.
    point.addEventListener('pointerenter', function () {
      if (point.classList.contains(CLASS_OPEN_POINT)) return
      placeTooltip(point)
    }, options)

    point.addEventListener('focusin', function (event) {
      if (point.classList.contains(CLASS_OPEN_POINT)) return
      if (point.contains(event.relatedTarget)) return
      placeTooltip(point)
    }, options)

    // A dismissed tooltip stays hidden until the pointer AND focus are gone.
    point.addEventListener('pointerleave', function () {
      if (point.contains(document.activeElement)) return
      point.classList.remove(CLASS_DISMISSED)
    }, options)

    point.addEventListener('focusout', function (event) {
      if (point.contains(event.relatedTarget)) return
      if (point.matches(':hover')) return
      point.classList.remove(CLASS_DISMISSED)
    }, options)

    if (!button) return

    button.addEventListener('pointerdown', function (event) {
      pressPointers.set(button, event.pointerType)
    }, options)

    // A native button also fires click for Enter / Space.
    button.addEventListener('click', function (event) {
      const pointerType = pressPointers.get(button) || ''
      pressPointers.delete(button)

      // Hover trigger: the mouse opened it by hovering and the keyboard by
      // focusing — only a tap needs JS.
      if (!clickTrigger && TAP_POINTERS.indexOf(pointerType) === -1) return

      event.preventDefault()
      event.stopPropagation()
      togglePoint(point)
    }, options)
  }

  /**
   * Install document-level listeners once (outside click + Escape).
   */
  function bindDocumentListeners() {
    if (documentListenersBound) return
    documentListenersBound = true

    document.addEventListener('click', function (event) {
      const target = event.target
      if (!target) return

      // If the click fell inside a point (button or tooltip), let that
      // element's own handler decide. Links inside the tooltip navigate normally.
      if (target.closest && target.closest(SELECTOR_POINT)) {
        return
      }

      closeAllOpen(document)
    })

    document.addEventListener('keydown', function (event) {
      if (event.key !== 'Escape') return

      // Hovered / focused tooltips on the hover trigger (CSS reveal).
      document.querySelectorAll(SELECTOR_ENGAGED).forEach(function (point) {
        point.classList.add(CLASS_DISMISSED)
      })

      // Click / tap tooltips (JS open state). The click trigger hands focus back
      // to its pin; a tapped hover pin must not, or focus would reveal it again.
      document.querySelectorAll('.' + CLASS_OPEN_POINT).forEach(function (point) {
        closePoint(point)

        if (!isClickTrigger(point)) return

        const button = point.querySelector(SELECTOR_HOTSPOT)
        if (button) {
          button.focus()
        }
      })
    })
  }

  // ------------------------------------------------------------------------
  // Init / reset
  // ------------------------------------------------------------------------

  /**
   * Initialize every hotspot point inside the given scope.
   *
   * @param {ParentNode} [root=document] Root node to scan.
   */
  window.Themeasy.hotspotImage.init = function (root) {
    const scope = root || document

    const points = scope.querySelectorAll(SELECTOR_WRAPPER + ' ' + SELECTOR_POINT)
    if (!points.length) return

    points.forEach(bindPoint)
    bindDocumentListeners()
  }

  /**
   * Drop listeners and transient state (open, dismissed, placement) so init()
   * can rebuild — used by the Elementor preview before each re-init.
   *
   * @param {ParentNode} [root=document] Root node to scan.
   */
  window.Themeasy.hotspotImage.reset = function (root) {
    const scope = root || document

    scope.querySelectorAll(SELECTOR_POINT).forEach(function (point) {
      const controller = bindings.get(point)
      if (controller) {
        controller.abort()
        bindings.delete(point)
      }

      closePoint(point)
      point.classList.remove(CLASS_DISMISSED)

      const tooltip = point.querySelector(SELECTOR_TOOLTIP)
      if (tooltip && tooltip.dataset.preferredPosition) {
        tooltip.dataset.position = tooltip.dataset.preferredPosition
        delete tooltip.dataset.preferredPosition
        tooltip.style.removeProperty(PROP_SHIFT)
      }
    })
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WRAPPER)) {
      window.Themeasy.hotspotImage.init()
    }
  }

  window.Themeasy.hotspotImage.boot = boot

  onDomReady(function () {
    window.Themeasy.hotspotImage.boot()
  })

})(window, document)
